// React component with p5.js integration
import React, { useEffect } from 'react';
import p5 from 'p5';
import './Chalkboard.styles.scss';

const Chalkboard = ({ socket, tool, color, username }) => {
  useEffect(() => {
    const sketch = (p) => {
      let canvas;

      p.setup = () => {
        canvas = p.createCanvas(window.innerWidth - 300, window.innerHeight - 64);
        canvas.parent('chalkboard-container');
        p.background(255);
      };

      p.windowResized = () => {
        p.resizeCanvas(window.innerWidth - 300, window.innerHeight - 64);
      };

      // Drawing logic for different tools
      p.mouseDragged = () => {
        if (tool === 'pen') {
          drawLine(p.pmouseX, p.pmouseY, p.mouseX, p.mouseY);
        }
      };

      p.mousePressed = () => {
        if (tool === 'circle') {
          startX = p.mouseX;
          startY = p.mouseY;
        }
      };

      p.mouseReleased = () => {
        if (tool === 'circle') {
          const radius = p.dist(startX, startY, p.mouseX, p.mouseY);
          drawCircle(startX, startY, radius);
        }
      };

      const drawLine = (x1, y1, x2, y2) => {
        const data = { x1, y1, x2, y2, color, weight: 4 };
        p.stroke(color);
        p.strokeWeight(4);
        p.line(x1, y1, x2, y2);
        socket.emit('line', data);
      };

      const drawCircle = (x, y, radius) => {
        const data = { x, y, radius, color };
        p.fill(color);
        p.noStroke();
        p.circle(x, y, radius * 2);
        socket.emit('circle', data);
      };
    };

    new p5(sketch);
  }, [socket, tool, color]);

  return <div id="chalkboard-container" className="chalkboard" />;
};

export default Chalkboard;

// Socket.IO client setup and event handling
import io from 'socket.io-client';

class SocketService {
  constructor() {
    this.socket = null;
  }

  connect(username) {
    this.socket = io.connect('/', {
      query: { username }
    });

    return new Promise((resolve) => {
      this.socket.on('connect', () => {
        console.log('Connected to server');
        resolve();
      });
    });
  }

  onNewUser(callback) {
    this.socket.on('new-user', callback);
  }

  onDrawingEvent(eventType, callback) {
    this.socket.on(eventType, (data) => {
      callback(data);
    });
  }

  emitDrawing(eventType, data) {
    this.socket.emit(eventType, data);
  }

  getUsers() {
    return fetch('/users')
      .then(res => res.json());
  }

  disconnect() {
    if (this.socket) {
      this.socket.disconnect();
    }
  }
}

export default new SocketService();

