// Socket.IO server implementation
const socket = require('socket.io');
const app = require('./app');

const userCache = [];

// User presence endpoint
app.get('/users', (req, res) => {
  res.status(200).send(userCache);
});

// Clean up inactive users
setInterval(() => {
  if (userCache.length > 0) {
    userCache.shift();
  }
}, 60000);

// Start server
const PORT = process.env.PORT || 3000;
const server = app.listen(PORT, () => {
  console.log(`App running on port ${PORT}...`);
});

// Socket.IO setup
const io = socket(server);

io.sockets.on('connection', (socket) => {
  console.log('New connection:', socket.id);

  // Handle user joining
  const newUser = socket.handshake.query['username'];
  userCache.push(newUser);
  socket.broadcast.emit('new-user', newUser);

  // Drawing event handlers
  const drawingEvents = ['line', 'circle', 'square'];

  drawingEvents.forEach(eventType => {
    socket.on(eventType, (data) => {
      // Validate data before broadcasting
      if (isValidDrawingData(data)) {
        socket.broadcast.emit(eventType, data);
      }
    });
  });

  // Handle disconnection
  socket.on('disconnect', () => {
    console.log('User disconnected:', socket.id);
    const index = userCache.indexOf(newUser);
    if (index > -1) {
      userCache.splice(index, 1);
    }
  });
});

function isValidDrawingData(data) {
  // Basic validation
  return data && 
    typeof data === 'object' &&
    data.hasOwnProperty('color') &&
    /^#[0-9A-F]{6}$/i.test(data.color);
}

// Graceful shutdown
process.on('SIGTERM', () => {
  console.log('SIGTERM RECEIVED! Shutting Down');
  server.close(() => {
    console.log('PROCESS TERMINATED!');
  });
});

// Express app with security middleware
const path = require('path');
const express = require('express');
const rateLimit = require('express-rate-limit');
const helmet = require('helmet');
const xssClean = require('xss-clean');
const compression = require('compression');
const cors = require('cors');

const app = express();

// Trust proxy for accurate IP addresses
app.enable('trust proxy');

// CORS configuration
app.use(cors({
  origin: process.env.CLIENT_URL || 'http://localhost:3000',
  credentials: true
}));

// Security headers
app.use(helmet({
  contentSecurityPolicy: {
    directives: {
      defaultSrc: ["'self'"],
      styleSrc: ["'self'", "'unsafe-inline'"],
      scriptSrc: ["'self'", "'unsafe-inline'", "'unsafe-eval'"],
      imgSrc: ["'self'", "data:", "https:"],
      connectSrc: ["'self'", "ws:", "wss:"]
    }
  }
}));

// Rate limiting
const limiter = rateLimit({
  max: 100,
  windowMs: 60 * 60 * 1000, // 1 hour
  message: 'Too many requests from this IP, please try again in an hour.',
  standardHeaders: true,
  legacyHeaders: false,
});

app.use('/api', limiter);

// Body parsing middleware
app.use(express.json({ limit: '10kb' }));
app.use(express.urlencoded({ extended: true, limit: '10kb' }));

// Data sanitization against XSS
app.use(xssClean());

// Compression middleware
app.use(compression());

// Serve static files
app.use(express.static(path.join(__dirname, '../client/build')));

// Catch all handler
app.get('*', (req, res) => {
  res.sendFile(path.join(__dirname, '../client/build', 'index.html'));
});

module.exports = app;

